'use client'; // se usi App Router

import { useState, useEffect } from 'react';

export default function PasswordManagerPage() {
  const [UserId, SetUserId] = useState('');
  type SubAccount = {
    id: string;
    title: string;
    username: string;
    password_encrypted: string;
    url: string;
  };

  const [SubAccounts, SetSubAccounts] = useState<SubAccount[]>([]);
  const [IsLoggedIn, SetIsLoggedIn] = useState(false);
  const [ErrorMessage, SetErrorMessage] = useState('');

  const FetchSubAccounts = async () => {
    try {
      const response = await fetch(`/api/subaccounts?userId=${UserId}`);
      if (!response.ok) {
        throw new Error('Errore nella chiamata API');
      }
      const data = await response.json();
      SetSubAccounts(data.subaccounts);
    } catch (error) {
      SetErrorMessage('Errore nel recupero dei SubAccount.');
      console.error(error);
    }
  };

  const HandleLogin = () => {
    if (UserId.trim() !== '') {
      SetIsLoggedIn(true);
    }
  };

  useEffect(() => {
    if (IsLoggedIn) {
      FetchSubAccounts();
    }
  }, [IsLoggedIn]);

  return (
    <div style={{ maxWidth: '600px', margin: 'auto', padding: '1rem' }}>
      {!IsLoggedIn ? (
        <div>
          <h2>Login</h2>
          <input
            type="text"
            placeholder="Inserisci il tuo UserId"
            value={UserId}
            onChange={(e) => SetUserId(e.target.value)}
            style={{ width: '100%', padding: '0.5rem', marginBottom: '1rem' }}
          />
          <button onClick={HandleLogin} style={{ padding: '0.5rem 1rem' }}>
            Accedi
          </button>
        </div>
      ) : (
        <div>
          <h2>Subaccount dell'utente {UserId}</h2>
          {ErrorMessage && <p style={{ color: 'red' }}>{ErrorMessage}</p>}
          {SubAccounts.map((sub) => (
            <div key={sub.id} style={{ border: '1px solid #ccc', padding: '1rem', marginBottom: '1rem' }}>
              <p><strong>Titolo:</strong> {sub.title}</p>
              <p><strong>Username:</strong> {sub.username}</p>
              <p><strong>Password Cifrata:</strong> {sub.password_encrypted}</p>
              <p><strong>URL:</strong> {sub.url}</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
